import{z as o,x as d,o as t,c as i,q as B,j as n,D as e,d as r,s,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"k-d 树","description":"","frontmatter":{"title":"k-d 树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kd-tree.md","filePath":"cs/kd-tree.md","lastUpdated":1791413859000}'),p={name:"cs/kd-tree.md"};function C(m,a,D,k,h,u){const A=d("Mermaid");return t(),i("div",null,[a[2]||(a[2]=B('<h1 id="k-d-树" tabindex="-1">k-d 树 <a class="header-anchor" href="#k-d-树" aria-label="Permalink to &quot;k-d 树&quot;">​</a></h1><div class="epigraph"><p>各层轮换轴，用中位数把点集切开；范围查询在包围盒与查询矩形不相交时剪枝。</p><footer>—— 据 Bentley, Multidimensional Binary Search Trees Used for Associative Searching, CACM 1975；Preparata and Shamos 整理</footer></div><p><a href="/cs/interval-tree">上一课</a> 在一维区间上剪枝。平面（或 \\(k\\) 维）点集：问矩形里有哪些点，或最近邻。本课不维护 maxR。缺口是 k-d 树：循环选维、按该维坐标 BST 分裂。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 个点在 \\(\\mathbb{R}^k\\)。正交范围查询。对半按 \\(x\\) 再按 \\(y\\)……建树，\\(\\Theta(n\\log n)\\) 可建（每次找中位数）。节点存点或存分裂值。查询矩形 \\(R\\)：当前分裂轴把空间切成两半，与 \\(R\\) 相交的一侧才递归；点在 \\(R\\) 内则报告。缺口是<strong>轴循环的二叉空间划分</strong>，不是 \\(k\\) 叉。</p><p><span class="marginnote">直觉类比：k-d 树像切蛋糕——先竖切一刀（按 x 选居中位置），每块里再横切一刀（按 y），如此交替。每刀都把一块切成两半，查询时只看与「查询窗口」重叠的那几块。</span></p><p>最坏查询可到 \\(\\Theta(n^{1-1/k}+m)\\) 一类界（平面约 \\(\\sqrt{n}\\)），平均更好。不要宣传成永远对数。</p><p><span class="marginnote">Bentley 1975, <em>CACM</em>。最近邻沿优先队列扩球，本课点名，不把所有启发式写完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>静态：预排序各维或线性时间中位数。动态插入破坏平衡，可定期重建或用替罪羊思想，本课以静态为主。维数 \\(k\\) 大时，近邻与范围剪枝失效（距离集中），这是后课 LSH 的动机，本课只警告。</p><p><span class="marginnote">常见误区：以为维数越高 k-d 树照样神速。实际上 \\(k{=}50\\) 时点与点的距离几乎一样远（距离集中），剪枝条件几乎不成立，查询退化成近似全扫——高维得换 LSH 或近似最近邻索引。</span></p>',11)),(t(),n(l,null,{default:e(()=>[s(A,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%82%B9%E9%9B%86%22%5D%20--%3E%20X%5B%22%E5%81%B6%E6%95%B0%E5%B1%82%3A%20%E6%8C%89%20x%20%E4%B8%AD%E4%BD%8D%E6%95%B0%22%5D%0A%20%20P%20--%3E%20Y%5B%22%E5%A5%87%E6%95%B0%E5%B1%82%3A%20%E6%8C%89%20y%20%E4%B8%AD%E4%BD%8D%E6%95%B0%22%5D%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%E7%9F%A9%E5%BD%A2%22%5D%20--%3E%20CLIP%5B%22%E4%B8%8E%E5%8D%8A%E5%B9%B3%E9%9D%A2%E7%9B%B8%E4%BA%A4%E6%89%8D%E8%BF%9B%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与四叉树：k-d 每次一轴二分；四叉按中点四块，形状不同。与 R 树：R 树包的是矩形 MBR，面向磁盘页。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"剪枝正确性：包围盒（由分裂历史推出）与 \\(R\\) 不相交则子树无点。更新一个点可能让树失衡，动态几何更常换 R 树或定期重建。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"数字实例：二维、一百万个点，一次最坏矩形查询要碰约 \\(n^{1-1/2} = \\sqrt{n} \\approx 1000\\) 个节点——而不是 \\(\\log_2 10^6 \\approx 20\\) 个。「不要宣传成永远对数」说的就是这个差距。")],-1)),(t(),n(l,null,{default:e(()=>[s(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E8%AE%BF%E9%97%AE%E8%8A%82%E7%82%B9%EF%BC%9A%E5%88%86%E8%A3%82%E8%BD%B4%20v%EF%BC%8C%E5%88%86%E8%A3%82%E5%80%BC%20s%22%5D%20--%3E%20C1%5B%22%E7%9F%A9%E5%BD%A2%20R%20%E5%9C%A8%E5%88%86%E8%A3%82%E7%BA%BF%E5%93%AA%E4%BE%A7%EF%BC%9F%22%5D%0A%20%20C1%20--%3E%7C%22R%20%E5%AE%8C%E5%85%A8%E5%9C%A8%E5%B7%A6%22%7C%20L%5B%22%E5%8F%AA%E9%80%92%E5%BD%92%E5%B7%A6%E5%AD%90%E6%A0%91%22%5D%0A%20%20C1%20--%3E%7C%22R%20%E5%AE%8C%E5%85%A8%E5%9C%A8%E5%8F%B3%22%7C%20RR%5B%22%E5%8F%AA%E9%80%92%E5%BD%92%E5%8F%B3%E5%AD%90%E6%A0%91%22%5D%0A%20%20C1%20--%3E%7C%22R%20%E6%A8%AA%E8%B7%A8%E5%88%86%E8%A3%82%E7%BA%BF%22%7C%20B%5B%22%E4%B8%A4%E4%BE%A7%E9%83%BD%E5%BE%97%E9%80%92%E5%BD%92%22%5D%0A%20%20N%20--%3E%20P%5B%22%E6%9C%AC%E8%8A%82%E7%82%B9%E5%AD%98%E7%9A%84%E7%82%B9%E8%90%BD%E5%9C%A8%20R%20%E5%86%85%EF%BC%9F%22%5D%0A%20%20P%20--%3E%7C%22%E6%98%AF%22%7C%20RE%5B%22%E6%8A%A5%E5%91%8A%E8%AF%A5%E7%82%B9%22%5D%0A%20%20P%20--%3E%7C%22%E5%90%A6%22%7C%20SK%5B%22%E8%B7%B3%E8%BF%87%EF%BC%8C%E7%BB%A7%E7%BB%AD%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=B('<p>点就是 \\(\\mathbb{R}^k\\) 记录。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>高维、磁盘块、或允许矩形重叠的分页索引：下一课 R 树。k-d 树不是 GIS 默认外存结构。</p><p>后课默认：内存静态点集正交查询可用 k-d。外存矩形用 R 树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>k-d 树：轮换轴的多维 BST，范围查询可剪枝。</li><li>最坏不是 \\(O(\\log n)\\)；高维退化。</li><li>外存矩形索引进 R 树。</li><li>出处：Bentley, <em>CACM</em>, 1975；Preparata and Shamos。</li></ul>',6))])}const R=o(p,[["render",C]]);export{f as __pageData,R as default};
